 11	public class MessageService {
 12	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
 13	    private static final String TEST_EMAIL = "testes@pousadamarealta.com.br";
 14	
 15	    private final List<Message> messages = new ArrayList<>();
 16	    private long messageIdCounter = 1;
 17	    private final boolean testMode;
 18	
 19	    public MessageService(boolean testMode) {
 20	        this.testMode = testMode;
 21	    }
 22	
 23	    public Message sendEmail(String to, String subject, String body) {
 24	        Message message;
 25	
 26	        if (!EmailValidator.isValid(to)) {
 27	            message = new Message(messageIdCounter++, MessageChannel.EMAIL, to, subject, body, MessageStatus.BLOCKED);
 28	            messages.add(message);
 29	            return message;
 30	        }
 31	
 32	        String finalTo = to;
 33	        String finalSubject = subject;
 34	        String finalBody = body;
 35	
 36	        if (testMode) {
 37	            finalTo = TEST_EMAIL;
 38	            finalSubject = "[TESTE] " + subject;
 39	            finalBody = "Destinatário original: " + to + "\n\n" + body;
 40	        }
 41	
 42	        message = new Message(messageIdCounter++, MessageChannel.EMAIL, finalTo, finalSubject, finalBody, MessageStatus.SENT);
 43	        messages.add(message);
 44	
 45	        if (!testMode && EmailValidator.isValid(to)) {
 46	            Message archiveMessage = new Message(messageIdCounter++, MessageChannel.EMAIL, ARCHIVE_EMAIL,
 47	                    "[Cópia] " + subject, body, MessageStatus.SENT);
 48	            messages.add(archiveMessage);
 49	        }
 50	
 51	        return message;
 52	    }
 53	
 54	    public List<Message> getMessages() {
 55	        return new ArrayList<>(messages);
 56	    }
 57	
 58	    public void clear() {
 59	        messages.clear();
 60	        messageIdCounter = 1;
 61	    }
 62	}
