 65	public class EmailValidator {
 66	    public static boolean isValid(String email) {
 67	        if (email == null || email.isEmpty()) {
 68	            return false;
 69	        }
 70	
 71	        int atCount = 0;
 72	        int atIndex = -1;
 73	
 74	        for (int i = 0; i < email.length(); i++) {
 75	            if (email.charAt(i) == '@') {
 76	                atCount++;
 77	                atIndex = i;
 78	            }
 79	        }
 80	
 81	        if (atCount != 1) {
 82	            return false;
 83	        }
 84	
 85	        if (atIndex == 0 || atIndex == email.length() - 1) {
 86	            return false;
 87	        }
 88	
 89	        String domain = email.substring(atIndex + 1);
 90	
 91	        int dotCount = 0;
 92	        for (char c : domain.toCharArray()) {
 93	            if (c == '.') {
 94	                dotCount++;
 95	            }
 96	        }
 97	
 98	        if (dotCount < 1) {
 99	            return false;
100	        }
101	
102	        if (domain.startsWith(".") || domain.endsWith(".")) {
103	            return false;
104	        }
105	
106	        return true;
107	    }
108	}
