 65	                        ratePlan = RatePlan.valueOf(request.ratePlan);
 66	                    } catch (IllegalArgumentException e) {
 67	                        ctx.status(400);
 68	                        ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
 69	                        return;
 70	                    }
 71	
 72	                    Reservation reservation = reservationService.createReservation(
 73	                            request.roomNumber,
 74	                            request.guestName,
 75	                            request.guestEmail,
 76	                            request.guestCpf,
 77	                            checkInDate,
 78	                            checkOutDate,
 79	                            request.guests,
 80	                            ratePlan
 81	                    );
 82	
 83	                    ctx.status(201);
 84	                    ctx.json(ReservationResponse.from(reservation));
 85	                } catch (Exception e) {
 86	                    ctx.status(400);
 87	                    ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
 88	                }
 89	            } catch (Exception e) {
 90	                ctx.status(400);
 91	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid request body"));
 92	            }
 93	        });
 94	
 95	        // GET /reservations/{id}
