106	            } catch (NumberFormatException e) {
107	                ctx.status(404);
108	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
109	            }
110	        });
111	
112	        // POST /reservations/{id}/confirmation
113	        app.post("/reservations/{id}/confirmation", ctx -> {
114	            try {
115	                long id = Long.parseLong(ctx.pathParam("id"));
