129	            } catch (NumberFormatException e) {
130	                ctx.status(404);
131	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
132	            }
133	        });
134	
135	        // POST /reservations/{id}/check-in
