137	            try {
138	                long id = Long.parseLong(ctx.pathParam("id"));
139	                Reservation reservation = reservationService.getReservation(id);
140	                if (reservation == null) {
141	                    ctx.status(404);
142	                    ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
143	                    return;
144	                }
145	
146	                try {
147	                    Reservation checkedIn = reservationService.checkIn(id);
148	                    ctx.json(ReservationResponse.from(checkedIn));
149	                } catch (IllegalArgumentException e) {
150	                    handleReservationError(ctx, e.getMessage());
151	                }
152	            } catch (NumberFormatException e) {
153	                ctx.status(404);
154	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
155	            }
156	        });
157	
158	        // POST /reservations/{id}/check-out
159	        app.post("/reservations/{id}/check-out", ctx -> {
160	            try {
161	                long id = Long.parseLong(ctx.pathParam("id"));
162	                Reservation reservation = reservationService.getReservation(id);
163	                if (reservation == null) {
164	                    ctx.status(404);
165	                    ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
166	                    return;
167	                }
168	
169	                try {
170	                    String comprovante = reservationService.checkOut(id);
171	                    ctx.header("Content-Type", "text/plain; charset=utf-8");
172	                    ctx.result(comprovante);
