221	                    handleReservationError(ctx, e.getMessage());
222	                }
223	            } catch (NumberFormatException e) {
224	                ctx.status(404);
225	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
226	            }
227	        });
228	
229	        // GET /messages
230	        app.get("/messages", ctx -> {
231	            var messages = messageService.getMessages().stream()
232	                    .map(MessageResponse::from)
233	                    .collect(Collectors.toList());
234	            ctx.json(messages);
