236	
237	        // GET /reports/occupancy
238	        app.get("/reports/occupancy", ctx -> {
239	            String dateStr = ctx.queryParam("date");
240	            if (dateStr == null || dateStr.isEmpty()) {
241	                ctx.status(400);
242	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
243	                return;
244	            }
245	
246	            try {
247	                LocalDate date = LocalDate.parse(dateStr);
248	                String report = reportService.generateOccupancyReport(date);
249	                ctx.header("Content-Type", "text/csv; charset=utf-8");
250	                ctx.result(report);
251	            } catch (Exception e) {
252	                ctx.status(400);
253	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
254	            }
255	        });
256	
257	        // GET /reports/revenue
258	        app.get("/reports/revenue", ctx -> {
259	            String monthStr = ctx.queryParam("month");
260	            if (monthStr == null || monthStr.isEmpty()) {
261	                ctx.status(400);
262	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
263	                return;
264	            }
265	
266	            try {
267	                YearMonth month = YearMonth.parse(monthStr);
268	                String report = reportService.generateRevenueReport(month);
269	                ctx.header("Content-Type", "text/csv; charset=utf-8");
270	                ctx.result(report);
271	            } catch (Exception e) {
272	                ctx.status(400);
273	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
274	            }
275	        });
276	    }
277	
278	    private static void handleReservationError(io.javalin.http.Context ctx, String error) {
279	        switch (error) {
280	            case "ROOM_NOT_FOUND" -> {
281	                ctx.status(404);
282	                ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
283	            }
284	            case "ROOM_UNAVAILABLE" -> {
285	                ctx.status(409);
286	                ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for selected dates"));
287	            }
288	            case "CAPACITY_EXCEEDED" -> {
289	                ctx.status(422);
290	                ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
291	            }
292	            case "OPERATION_NOT_ALLOWED" -> {
293	                ctx.status(409);
294	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "This operation is not allowed for the current reservation status"));
295	            }
296	            case "INVALID_REQUEST" -> {
297	                ctx.status(400);
298	                ctx.json(new ErrorResponse("INVALID_REQUEST", error));
299	            }
300	            default -> {
301	                ctx.status(400);
302	                ctx.json(new ErrorResponse("INVALID_REQUEST", error));
303	            }
304	        }
305	    }
306	}

