278	    private static void handleReservationError(io.javalin.http.Context ctx, String error) {
279	        switch (error) {
280	            case "ROOM_NOT_FOUND" -> {
281	                ctx.status(404);
282	                ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
283	            }
284	            case "ROOM_UNAVAILABLE" -> {
285	                ctx.status(409);
286	                ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for selected dates"));
287	            }
288	            case "CAPACITY_EXCEEDED" -> {
289	                ctx.status(422);
290	                ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
291	            }
292	            case "OPERATION_NOT_ALLOWED" -> {
293	                ctx.status(409);
294	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "This operation is not allowed for the current reservation status"));
295	            }
296	            case "INVALID_REQUEST" -> {
297	                ctx.status(400);
298	                ctx.json(new ErrorResponse("INVALID_REQUEST", error));
299	            }
300	            default -> {
301	                ctx.status(400);
302	                ctx.json(new ErrorResponse("INVALID_REQUEST", error));
303	            }
304	        }
305	    }
