 10	public class ReservationService {
 11	    private final List<Reservation> reservations = new ArrayList<>();
 12	    private final Map<Integer, Room> rooms = new HashMap<>();
 13	    private long reservationIdCounter = 1;
 14	    private final MessageService messageService;
