 33	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
 34	                                         LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
 35	        Room room = rooms.get(roomNumber);
 36	        if (room == null) {
 37	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
 38	        }
 39	
 40	        if (guests < 1 || guests > room.getCapacity()) {
 41	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
 42	        }
 43	
 44	        if (!checkOut.isAfter(checkIn)) {
 45	            throw new IllegalArgumentException("INVALID_REQUEST");
 46	        }
 47	
 48	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
 49	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
 50	        }
 51	
 52	        int nights = DateUtils.daysInRange(checkIn, checkOut);
 53	        double subtotal = calculateSubtotal(room, checkIn, checkOut);
 54	        double discount = calculateDiscount(subtotal, ratePlan);
 55	        double total = Money.subtract(subtotal, discount);
 56	
 57	        Reservation reservation = new Reservation(
 58	                reservationIdCounter++,
 59	                roomNumber,
 60	                guestName,
 61	                guestEmail,
 62	                guestCpf,
 63	                checkIn,
 64	                checkOut,
 65	                guests,
 66	                ratePlan,
 67	                nights,
 68	                subtotal,
 69	                discount,
 70	                total
 71	        );
 72	
 73	        reservations.add(reservation);
 74	        return reservation;
 75	    }
