 84	    public Reservation confirmReservation(long id, double amountPaid) {
 85	        Reservation reservation = getReservation(id);
 86	        if (reservation == null) {
 87	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
 88	        }
 89	
 90	        if (reservation.getStatus() != ReservationStatus.PENDING) {
 91	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
 92	        }
 93	
 94	        reservation.setStatus(ReservationStatus.CONFIRMED);
 95	        reservation.setAmountPaid(amountPaid);
 96	
 97	        String comprovante = generateComprovante(reservation);
 98	        sendConfirmationEmail(reservation, comprovante);
 99	
100	        return reservation;
101	    }
