119	        if (reservation == null) {
120	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
121	        }
122	
123	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
124	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
125	        }
126	
127	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
128	        return generateComprovante(reservation);
129	    }
