131	    public String getDocument(long id) {
132	        Reservation reservation = getReservation(id);
133	        if (reservation == null) {
134	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
135	        }
136	
137	        if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
138	            reservation.getStatus() != ReservationStatus.CHECKED_IN &&
139	            reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
140	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
141	        }
142	
143	        return generateComprovante(reservation);
144	    }
