146	    public Reservation cancelReservation(long id) {
147	        Reservation reservation = getReservation(id);
148	        if (reservation == null) {
149	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
150	        }
151	
152	        ReservationStatus status = reservation.getStatus();
153	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
154	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
155	        }
156	
157	        double refundAmount = 0;
158	
159	        if (status == ReservationStatus.CONFIRMED) {
160	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
161	                refundAmount = reservation.getAmountPaid();
162	            }
163	        }
164	
165	        reservation.setStatus(ReservationStatus.CANCELLED);
166	        if (refundAmount > 0) {
167	            reservation.setRefund(refundAmount);
168	        }
169	
170	        return reservation;
171	    }
