173	    private double calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
174	        double total = 0;
175	        LocalDate current = checkIn;
176	
177	        while (current.isBefore(checkOut)) {
178	            double nightPrice = room.getNightlyRate();
179	            if (DateUtils.isHighSeason(current)) {
180	                nightPrice = Money.round(nightPrice * 1.2);
181	            } else {
182	                nightPrice = Money.round(nightPrice);
183	            }
184	            total = Money.add(total, nightPrice);
185	            current = current.plusDays(1);
186	        }
187	
188	        return Money.round(total);
189	    }
190	
191	    private double calculateDiscount(double subtotal, RatePlan ratePlan) {
192	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
193	            return Money.applyPercentageDiscount(subtotal, 15);
194	        }
195	        return 0;
196	    }
