198	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
199	        LocalDate current = checkIn;
200	        while (current.isBefore(checkOut)) {
201	            LocalDate night = current;
202	            boolean occupied = reservations.stream()
203	                    .filter(r -> r.getRoomNumber() == roomNumber)
204	                    .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
205	                    .anyMatch(r -> !night.isBefore(r.getCheckIn()) && night.isBefore(r.getCheckOut()));
206	
207	            if (occupied) {
208	                return true;
209	            }
210	
211	            current = current.plusDays(1);
212	        }
213	        return false;
214	    }
