216	    private String generateComprovante(Reservation reservation) {
217	        Room room = rooms.get(reservation.getRoomNumber());
218	        StringBuilder sb = new StringBuilder();
219	
220	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
221	        sb.append("Hóspede: ").append(reservation.getGuestName()).append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
222	        sb.append("Quarto: ").append(reservation.getRoomNumber()).append(" (").append(room.getType()).append(")\n");
223	        sb.append("Entrada: ").append(DateUtils.formatForDisplay(reservation.getCheckIn())).append(" | ");
224	        sb.append("Saída: ").append(DateUtils.formatForDisplay(reservation.getCheckOut())).append(" | ");
225	        sb.append(reservation.getNights()).append(" ").append(reservation.getNights() == 1 ? "diária" : "diárias").append("\n");
226	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
227	
228	        if (reservation.getDiscount() > 0) {
229	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
230	        }
231	
232	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
233	
234	        return sb.toString();
235	    }
