252	    private String formatCpf(String cpf) {
253	        if (cpf == null || cpf.length() != 11) {
254	            return cpf;
255	        }
256	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
257	               cpf.substring(6, 9) + "-" + cpf.substring(9);
