288	    public String generateOccupancyReport(LocalDate date) {
289	        List<Reservation> reservations = reservationService.getReservations();
290	
291	        List<Reservation> occupied = reservations.stream()
292	                .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
293	                            r.getStatus() == ReservationStatus.CHECKED_IN ||
294	                            r.getStatus() == ReservationStatus.CHECKED_OUT)
295	                .filter(r -> !date.isBefore(r.getCheckIn()) && date.isBefore(r.getCheckOut()))
296	                .sorted((a, b) -> Integer.compare(a.getRoomNumber(), b.getRoomNumber()))
297	                .collect(Collectors.toList());
298	
299	        StringBuilder csv = new StringBuilder();
300	        csv.append("room,type,reservation,check_in,check_out\n");
301	
302	        for (Reservation r : occupied) {
303	            csv.append(r.getRoomNumber()).append(",");
304	            csv.append(r.getRoomNumber() / 100 == 1 ? "STANDARD" : (r.getRoomNumber() / 100 == 2 ? "DELUXE" : "SUITE")).append(",");
305	            csv.append(r.getId()).append(",");
306	            csv.append(DateUtils.formatForApi(r.getCheckIn())).append(",");
307	            csv.append(DateUtils.formatForApi(r.getCheckOut())).append("\n");
308	        }
309	
310	        csv.append("total,").append(occupied.size()).append("/5\n");
311	
312	        return csv.toString();
313	    }
