315	    public String generateRevenueReport(YearMonth month) {
316	        List<Reservation> reservations = reservationService.getReservations();
317	
318	        List<Reservation> monthlyReservations = reservations.stream()
319	                .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
320	                .filter(r -> {
321	                    if (r.getStatus() == ReservationStatus.CANCELLED) {
322	                        return r.getAmountPaid() > 0 || (r.getRefund() != null && r.getRefund() > 0);
323	                    }
324	                    return r.getAmountPaid() > 0;
325	                })
326	                .sorted((a, b) -> {
327	                    int dateCompare = a.getCheckIn().compareTo(b.getCheckIn());
328	                    if (dateCompare == 0) {
329	                        return Long.compare(a.getId(), b.getId());
330	                    }
331	                    return dateCompare;
332	                })
333	                .collect(Collectors.toList());
334	
335	        StringBuilder csv = new StringBuilder();
336	        csv.append("reservation,room,check_in,check_out,status,amount\n");
337	
338	        double total = 0;
339	
340	        for (Reservation r : monthlyReservations) {
