405	    public static boolean isValid(String email) {
406	        if (email == null || email.isEmpty()) {
407	            return false;
408	        }
409	
410	        int atCount = 0;
411	        int atIndex = -1;
412	
413	        for (int i = 0; i < email.length(); i++) {
414	            if (email.charAt(i) == '@') {
415	                atCount++;
416	                atIndex = i;
417	            }
418	        }
419	
420	        if (atCount != 1) {
421	            return false;
422	        }
423	
424	        if (atIndex == 0 || atIndex == email.length() - 1) {
425	            return false;
426	        }
427	
428	        String domain = email.substring(atIndex + 1);
429	
430	        int dotCount = 0;
431	        for (char c : domain.toCharArray()) {
432	            if (c == '.') {
433	                dotCount++;
434	            }
435	        }
436	
437	        if (dotCount < 1) {
438	            return false;
439	        }
440	
441	        if (domain.startsWith(".") || domain.endsWith(".")) {
442	            return false;
443	        }
444	
445	        return true;
446	    }
