     6	public class Money {
     7	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
     8	
     9	    public static double round(double value) {
    10	        BigDecimal bd = new BigDecimal(value);
    11	        bd = bd.setScale(2, ROUNDING_MODE);
    12	        return bd.doubleValue();
    13	    }
    14	
    15	    public static double applyPercentageDiscount(double value, double discountPercent) {
    16	        BigDecimal bd = new BigDecimal(value);
    17	        BigDecimal discount = new BigDecimal(discountPercent);
    18	        BigDecimal result = bd.multiply(discount.divide(new BigDecimal(100), 10, ROUNDING_MODE));
    19	        return result.setScale(2, ROUNDING_MODE).doubleValue();
    20	    }
    21	
    22	    public static double subtract(double a, double b) {
    23	        BigDecimal bda = new BigDecimal(a);
    24	        BigDecimal bdb = new BigDecimal(b);
    25	        return bda.subtract(bdb).setScale(2, ROUNDING_MODE).doubleValue();
    26	    }
    27	
