    97	        List<Reservation> occupied = reservations.stream()
    98	                .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
    99	                            r.getStatus() == ReservationStatus.CHECKED_IN ||
   100	                            r.getStatus() == ReservationStatus.CHECKED_OUT)
   101	                .filter(r -> !date.isBefore(r.getCheckIn()) && date.isBefore(r.getCheckOut()))
   102	                .sorted((a, b) -> Integer.compare(a.getRoomNumber(), b.getRoomNumber()))
   103	                .collect(Collectors.toList());
   104	
   105	        StringBuilder csv = new StringBuilder();
   106	        csv.append("room,type,reservation,check_in,check_out\n");
   107	
   108	        for (Reservation r : occupied) {
   109	            csv.append(r.getRoomNumber()).append(",");
   110	            csv.append(r.getRoomNumber() / 100 == 1 ? "STANDARD" : (r.getRoomNumber() / 100 == 2 ? "DELUXE" : "SUITE")).append(",");
   111	            csv.append(r.getId()).append(",");
   112	            csv.append(DateUtils.formatForApi(r.getCheckIn())).append(",");
   113	            csv.append(DateUtils.formatForApi(r.getCheckOut())).append("\n");
