   121	    public String generateRevenueReport(YearMonth month) {
   122	        List<Reservation> reservations = reservationService.getReservations();
   123	
   124	        List<Reservation> monthlyReservations = reservations.stream()
   125	                .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
   126	                .filter(r -> {
   127	                    if (r.getStatus() == ReservationStatus.CANCELLED) {
   128	                        return r.getAmountPaid() > 0 || (r.getRefund() != null && r.getRefund() > 0);
   129	                    }
   130	                    return r.getAmountPaid() > 0;
   131	                })
   132	                .sorted((a, b) -> {
   133	                    int dateCompare = a.getCheckIn().compareTo(b.getCheckIn());
   134	                    if (dateCompare == 0) {
   135	                        return Long.compare(a.getId(), b.getId());
   136	                    }
   137	                    return dateCompare;
   138	                })
   139	                .collect(Collectors.toList());
   140	
   141	        StringBuilder csv = new StringBuilder();
   142	        csv.append("reservation,room,check_in,check_out,status,amount\n");
   143	
   144	        double total = 0;
